    <p>${logout ? "\u3053\u306E\u30D6\u30E9\u30A6\u30B6\u306E\u7BA1\u7406\u753B\u9762\u304B\u3089\u30ED\u30B0\u30A2\u30A6\u30C8\u3057\u307E\u3059\u3002" : "\u30E6\u30FC\u30B6\u30FC\u540D\u306F\u4E0D\u8981\u3067\u3059\u3002\u7BA1\u7406\u7528\u30D1\u30B9\u30EF\u30FC\u30C9\u3060\u3051\u5165\u529B\u3057\u3066\u304F\u3060\u3055\u3044\u3002"}</p>
